static constexpr int g_t2sCharCount = 4113;

// Convert Traditional Chinese UTF-8 string to Simplified Chinese
// Note: Some OpenCC entries have multiple simplified forms separated by space (e.g. "覆 复").
// We always take the first form.
inline std::string T2S_Convert(const char* input) {
    if (!input) return {};
    std::string result;
    size_t len = strlen(input);
    size_t i = 0;
    while (i < len) {
        bool matched = false;
        // Try phrase match first (longest match)
        for (int p = 0; p < g_t2sPhraseCount; ++p) {
            size_t plen = strlen(g_t2sPhrases[p].tc);
            if (i + plen <= len && memcmp(input + i, g_t2sPhrases[p].tc, plen) == 0) {
                const char* sc = g_t2sPhrases[p].sc;
                const char* sp = strchr(sc, ' ');
                result.append(sc, sp ? (size_t)(sp - sc) : strlen(sc));
                i += plen;
                matched = true;
                break;
            }
        }
        if (matched) continue;
        // Try character match
        for (int c = 0; c < g_t2sCharCount; ++c) {
            size_t clen = strlen(g_t2sChars[c].tc);
            if (i + clen <= len && memcmp(input + i, g_t2sChars[c].tc, clen) == 0) {
                const char* sc = g_t2sChars[c].sc;
                const char* sp = strchr(sc, ' ');
                result.append(sc, sp ? (size_t)(sp - sc) : strlen(sc));
                i += clen;
                matched = true;
                break;
            }
        }
        if (matched) continue;
        // No match: copy one byte
        result += input[i++];
    }
    return result;
}
